import * as React from "react";
import "./PhoneNumberField.scss";
import { TextField } from "../textField";
import type { TextFieldProps } from "../textField";
import StaticCountry from "./StaticCountry/StaticCountry";
import type { StaticCountryProps } from "./StaticCountry/StaticCountry";
import { Verify, type VerifyProps } from "../verify";

export interface PhoneNumberFieldProps extends TextFieldProps {
  /**
   * Determines whether to show verification UI component
   */
  enableVerify?: boolean;

  /**
   * Indicates if the phone number is currently verified
   */
  verified?: boolean;

  /**
   * Custom country selector component (overrides default StaticCountry)
   */
  country?: React.ReactNode;

  /**
   * Custom verification component (overrides default Verify)
   */
  verify?: React.ReactNode;

  /**
   * Props for the default StaticCountry component
   */
  staticCountryProps?: StaticCountryProps;

  /**
   * Props for the default Verify component (excluding 'verified' and 'onClick')
   */
  verifyProps?: Omit<VerifyProps, "verified" | "onClick">;

  /**
   * Callback fired when verification is requested
   */
  onVerify?: () => void;
  /**
   * Supporting text when verification is successful
   */
  verifySuccessText?: string;
}

export const PhoneNumberField: React.FC<PhoneNumberFieldProps> = ({
  enableVerify = false,
  verified = false,
  country,
  verify,
  staticCountryProps,
  verifyProps,
  onVerify,
  verifySuccessText = "Successfully Verified",
  type = "number",
  supportingText,
  ...rest
}) => {
  const internalCountry = country ?? <StaticCountry {...staticCountryProps} />;
  const internalVerify = verify ?? (
    <Verify verified={verified} onClick={onVerify} {...verifyProps} />
  );
  const trailing = enableVerify ? internalVerify : undefined;
  const defaultSupportingText = (
    <div>
      Click <span className="bold-verify">verify</span> to validate your mobile
      number
    </div>
  );
  const successText = (
    <div className="phone-number-field verified-success">
      {verifySuccessText}
    </div>
  );
  const internalSupportingText = verified
    ? successText
    : supportingText ?? defaultSupportingText;
  return (
    <TextField
      leadingIcon={internalCountry}
      trailingIcon={trailing}
      type={type}
      supportingText={internalSupportingText}
      {...rest}
    />
  );
};

export default PhoneNumberField;
